export const connectorNames={CPU_SOCKET:'Zócalo del procesador',DIMM_SLOT:'Ranuras de memoria RAM',PCIE_SLOT:'Ranuras para tarjetas',POWER_CONNECTOR:'Conector de alimentación',PCIe_X16:'Ranura para la placa de video',PCIe_X1:'Ranura corta para tarjetas',M2_SLOT:'Conector para SSD M.2',SATA_PORT:'Puerto para discos SATA',ATX_POWER:'Alimentación principal de la placa',CPU_POWER:'Alimentación del procesador',FAN_HEADER:'Conector para ventilador'};
export const connectorHelp={CPU_SOCKET:'Acá se coloca el procesador. Su modelo debe ser compatible con el zócalo.',DIMM_SLOT:'Acá se instala la memoria RAM. Revisá el tipo y las posiciones recomendadas en el manual.',PCIE_SLOT:'Se usan para placas de video y otras tarjetas. La foto no confirma su versión ni cantidad de líneas.',POWER_CONNECTOR:'Lleva energía a la placa o al procesador. Consultá el manual para identificar el cable exacto; no los intercambies.'};
export function connectorName(type){return connectorNames[type]||'Conexión sin identificar'}
export function safeCommonsImage(url){try{const u=new URL(url);return u.protocol==='https:'&&['upload.wikimedia.org','thumb.wikimedia.org'].includes(u.hostname)&&!u.username&&!u.password}catch{return false}}
export function safeCommonsPage(url){try{const u=new URL(url);return u.protocol==='https:'&&u.hostname==='commons.wikimedia.org'&&!u.username&&!u.password}catch{return false}}
export function galleryQuery(query='',offset=0){const q=query.replace(/[^\p{L}\p{N} _.-]/gu,' ').trim().slice(0,80);const params=new URLSearchParams({action:'query',generator:'search',gsrsearch:`filetype:bitmap motherboard ${q} -laptop -notebook -zenbook -capacitor -chipset -backside`,gsrnamespace:'6',gsrlimit:'18',gsroffset:String(offset),prop:'imageinfo',iiprop:'url|extmetadata|size',iiurlwidth:'960',format:'json',origin:'*'});return 'https://commons.wikimedia.org/w/api.php?'+params}
export function mountGallery(onSelect){
 const $=s=>document.querySelector(s),grid=$('#board-gallery'),status=$('#gallery-status');let selected=null,items=[],generation=0,offset=0,query='',controller=null,loading=false;
 const plain=s=>new DOMParser().parseFromString(String(s||''),'text/html').body.textContent.trim().slice(0,250);
 function render(){grid.replaceChildren();for(const item of items){const card=document.createElement('article');card.className='board-card';const choose=document.createElement('button');choose.className='board-choice';choose.disabled=loading;choose.setAttribute('aria-label','Explorar '+item.name);const im=document.createElement('img');im.src=item.image;im.alt=item.name;im.loading='lazy';im.onerror=()=>{choose.disabled=true;im.alt='Imagen no disponible'};const name=document.createElement('strong');name.textContent=item.name;const call=document.createElement('span');call.textContent=selected===item.id?'Foto elegida':'Ver sus conectores';choose.append(im,name,call);choose.onclick=async()=>{if(loading)return;loading=true;selected=item.id;render();status.textContent='Abriendo la foto y buscando conexiones…';try{await onSelect(item);status.textContent='Foto elegida. Revisá las conexiones señaladas más abajo.'}catch{status.textContent='No pudimos abrir esa foto. Probá otra imagen o cargá un archivo.'}finally{loading=false;render()}};const credit=document.createElement('a');credit.href=item.source;credit.target='_blank';credit.rel='noopener noreferrer';credit.textContent=`${item.author||'Autor en la fuente'} · ${item.license||'Ver licencia'}`;card.append(choose,credit);grid.append(card)}}
 async function initial(){const serial=++generation;try{const r=await fetch('./gallery/catalog.json');if(!r.ok)throw Error();const data=await r.json();if(serial!==generation)return;items=data;render();status.textContent='Elegí una placa de la selección o buscá otras fotos por marca y modelo.'}catch{status.textContent='La selección no está disponible. Podés buscar en la biblioteca.'}}
 async function search(more=false){const serial=++generation;controller?.abort();controller=new AbortController();query=more?query:$('#gallery-query').value;const old=items;if(!more)offset=0;status.textContent='Buscando fotos de motherboards…';$('#gallery-more').hidden=true;const requestController=controller;const timeout=setTimeout(()=>requestController.abort(),15000);try{const r=await fetch(galleryQuery(query,offset),{signal:controller.signal});if(!r.ok)throw Error();const data=await r.json();if(data.error)throw Error();if(serial!==generation)return;const found=Object.values(data.query?.pages||{}).sort((a,b)=>(a.index||0)-(b.index||0)).flatMap(p=>{const i=p.imageinfo?.[0],meta=i?.extmetadata||{};if(!i||!safeCommonsImage(i.thumburl||i.url)||!safeCommonsPage(i.descriptionurl)||i.width<400||i.height<300||!meta.LicenseShortName?.value)return [];return [{id:p.pageid,name:p.title.replace(/^File:/,'').replace(/\.(jpg|jpeg|png|webp)$/i,'').replaceAll('_',' '),image:i.thumburl||i.url,source:i.descriptionurl,author:plain(meta.Artist?.value),license:plain(meta.LicenseShortName.value)}]});items=more?[...old,...found.filter(x=>!old.some(y=>y.id===x.id))]:found;offset=data.continue?.gsroffset??null;render();$('#gallery-more').hidden=offset===null;status.textContent=items.length?`${items.length} fotos disponibles. Los resultados pueden incluir detalles o placas antiguas; elegí una vista completa y nítida.`:'No encontramos fotos para ese modelo. Probá sólo con la marca o usá una foto propia.'}catch(e){if(serial===generation){status.textContent='No pudimos consultar la biblioteca. La selección de fotos y la carga de archivos siguen disponibles.';if(!items.length)await initial()}}finally{clearTimeout(timeout)}}
 $('#gallery-search').onsubmit=e=>{e.preventDefault();search()};$('#gallery-more').onclick=()=>search(true);$('#gallery-featured').onclick=()=>{generation++;controller?.abort();$('#gallery-more').hidden=true;$('#gallery-query').value='';initial()};initial();
}
